struct ring { int *buf; unsigned mask; unsigned head; /* producer */ unsigned tail; /* consumer */
              unsigned long long produced, consumed; };

void push(struct ring *r, int v) {
    unsigned h = r->head;                       // head = tail means FULL (one slot wasted)
    if (h == r->tail) { /* capacity policy: overwrite oldest */
        r->tail = (r->tail + 1) & r->mask;      // drop the oldest to make room
    }
    r->buf[h] = v;
    release_store(&r->head, (h + 1) & r->mask); // release: item visible BEFORE head is
}

int pop(struct ring *r) {
    unsigned t = r->tail;
    if (t == acquire_load(&r->head)) return -1;  // empty
    int v = r->buf[t];                          // acquire on head: item IS written
    r->tail = (t + 1) & r->mask;
    return v;
}
// power-of-two size -> the wrap is a mask; each side writes only its OWN index
// -> no lock, no CAS, one barrier per side. Sequence numbers detect overrun.
